<?php
class ShopReviewRatings { public static function all($productIds) { $ids=array_values(array_unique(array_filter(array_map('intval',(array)$productIds)))); if (!$ids || !ShopHelper::ensureReviewsTable()) return array(); $table=ShopHelper::table('reviews'); $rows=ShopHelper::db()->query("SELECT `product_id`, AVG(`rating`) AS avg_rating, COUNT(*) AS cnt FROM `{$table}` WHERE `active` = 1 AND `product_id` IN (".implode(',',$ids).") GROUP BY `product_id`"); $result=array(); foreach ($rows as $row) $result[(int)$row['product_id']]=array('avg'=>round((float)$row['avg_rating'],1),'count'=>(int)$row['cnt']); return $result; } public static function one($id) { $all=self::all(array((int)$id)); return isset($all[(int)$id])?$all[(int)$id]:array('avg'=>0.0,'count'=>0); } }
